"use client"

import { useState } from "react"

import { storyMedia } from "../media-assets"
import { downloadMedia } from "@/components/livepeer-ui/media-context-menu"
import { ClipsHeader, ClipsLibrary, type Clip } from "./clips-components"
import type { VideoBuddyPageContent } from "@/components/livepeer-ui/contracts"

const initialFootage: Clip[] = [
  {
    id: 3,
    name: "salt-flats-wind-test-04.mp4",
    duration: "0:18",
    uploaded: "Today, 3:08 PM",
    imageUrl: storyMedia.saltSignal.wide,
  },
  {
    id: 2,
    name: "lighthouse-weather-reference.mov",
    duration: "0:12",
    uploaded: "Yesterday",
    imageUrl: storyMedia.blackTide.wide,
  },
  {
    id: 1,
    name: "pool-rehearsal-wide.mp4",
    duration: "0:24",
    uploaded: "Jul 21",
    imageUrl: storyMedia.afterHours.wide,
  },
]

export function FootageWorkspace({ content }: { content: VideoBuddyPageContent }) {
  const [footage, setFootage] = useState(initialFootage)
  function addFootage(files: FileList | null) {
    if (!files?.length) return
    const additions = Array.from(files)
      .filter((file) => file.type.startsWith("video/"))
      .map((file, index) => ({
        id: (footage[0]?.id ?? 0) + index + 1,
        name: file.name,
        duration: "0:00",
        uploaded: "Just now",
        imageUrl: storyMedia.saltSignal.wide,
      }))
    setFootage((current) => [...additions.reverse(), ...current])
  }
  return (
    <main className="flex h-[calc(100dvh-4rem)] flex-col overflow-hidden md:h-dvh">
      <section className="min-h-0 flex-1 overflow-y-auto overscroll-none">
        <div className="mx-auto max-w-6xl px-4 pb-10 sm:px-6">
          <ClipsHeader
            title={content.heading!}
            actionLabel={content.primaryActionLabel!}
            onUpload={addFootage}
          />
          <ClipsLibrary
            clips={footage}
            emptyStateTitle={content.emptyStateTitle!}
            onDownload={(clip) => downloadMedia(clip.imageUrl, clip.name)}
            onDuplicate={(clip) =>
              setFootage((current) => [
                {
                  ...clip,
                  id: Math.max(...current.map((entry) => entry.id)) + 1,
                  name: `Copy of ${clip.name}`,
                  uploaded: "Just now",
                },
                ...current,
              ])
            }
            onRemove={(clip) =>
              setFootage((current) =>
                current.filter((entry) => entry.id !== clip.id)
              )
            }
          />
        </div>
      </section>
    </main>
  )
}

import { sanityStaticAssets } from "@/sanity/lib/static-assets"

export const storyMedia = {
  saltSignal: {
    wide: sanityStaticAssets.projectResults.saltSignal,
    character: sanityStaticAssets.projectResults.maraPortrait,
  },
  blackTide: {
    wide: sanityStaticAssets.projectResults.blackTide,
    character: sanityStaticAssets.projectResults.junePortrait,
  },
  afterHours: {
    wide: sanityStaticAssets.projectResults.afterHours,
    character: sanityStaticAssets.projectResults.eliPortrait,
  },
} as const

export const storyboardFrames = {
  slugGang: sanityStaticAssets.slugGangFrames,
  saltSignal: [
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.character,
    storyMedia.saltSignal.wide,
    storyMedia.saltSignal.wide,
  ],
  blackTide: [
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
    storyMedia.blackTide.wide,
    storyMedia.blackTide.character,
  ],
  afterHours: [
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
    storyMedia.afterHours.wide,
    storyMedia.afterHours.character,
  ],
} as const

export function frameAt(frames: readonly string[], index: number) {
  return frames[index % frames.length]
}

export function framesForName(name: string) {
  const normalized = name.toLowerCase()
  if (normalized.includes("tide") || normalized.includes("june")) {
    return storyboardFrames.blackTide
  }
  if (
    normalized.includes("after") ||
    normalized.includes("rehearsal") ||
    normalized.includes("eli")
  ) {
    return storyboardFrames.afterHours
  }
  return storyboardFrames.saltSignal
}

"use client"

import type { ComponentProps, ReactNode } from "react"
import {
  ArrowDownToLineIcon,
  CopyIcon,
  ExternalLinkIcon,
  RotateCwIcon,
  Trash2Icon,
} from "lucide-react"

import {
  ContextMenu,
  ContextMenuContent,
  ContextMenuItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@/components/ui/context-menu"
import { cn } from "@/lib/utils"

type MediaContextMenuProps = {
  children: ReactNode
  className?: string
  triggerProps?: Omit<ComponentProps<"div">, "children" | "className">
  onOpen?: () => void
  openLabel?: string
  onDownload?: () => void
  onDuplicate?: () => void
  duplicateLabel?: string
  onRemove?: () => void
  removeLabel?: string
}

export function MediaContextMenu({
  children,
  className,
  triggerProps,
  onOpen,
  openLabel = "Open",
  onDownload,
  onDuplicate,
  duplicateLabel = "Duplicate",
  onRemove,
  removeLabel = "Remove",
}: MediaContextMenuProps) {
  return (
    <ContextMenu>
      <ContextMenuTrigger
        className={cn("min-w-0", className)}
        {...triggerProps}
      >
        {children}
      </ContextMenuTrigger>
      <ContextMenuContent>
        {onOpen && (
          <ContextMenuItem onClick={onOpen}>
            <ExternalLinkIcon />
            {openLabel}
          </ContextMenuItem>
        )}
        {onDownload && (
          <ContextMenuItem onClick={onDownload}>
            <ArrowDownToLineIcon />
            Download
          </ContextMenuItem>
        )}
        {onDuplicate && (
          <ContextMenuItem onClick={onDuplicate}>
            {duplicateLabel.toLowerCase().includes("reroll") ? (
              <RotateCwIcon />
            ) : (
              <CopyIcon />
            )}
            {duplicateLabel}
          </ContextMenuItem>
        )}
        {onRemove && (
          <>
            <ContextMenuSeparator />
            <ContextMenuItem variant="destructive" onClick={onRemove}>
              <Trash2Icon />
              {removeLabel}
            </ContextMenuItem>
          </>
        )}
      </ContextMenuContent>
    </ContextMenu>
  )
}

export function downloadMedia(url: string, filename: string) {
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = filename
  anchor.click()
}

