"use client"
import { useRef } from "react"
import { PlusIcon } from "lucide-react"
import { Button } from "@/components/ui/button"
export function ClipsHeader({
  title,
  actionLabel,
  onUpload,
}: {
  title: string
  actionLabel: string
  onUpload: (files: FileList | null) => void
}) {
  const uploadRef = useRef<HTMLInputElement>(null)
  return (
    <header className="flex items-center justify-between gap-4 py-4">
      <h1 className="text-xl font-medium">{title}</h1>
      <Button className="h-10 px-5" onClick={() => uploadRef.current?.click()}>
        <PlusIcon className="size-6" />
        {actionLabel}
      </Button>
      <input
        ref={uploadRef}
        type="file"
        accept="video/*"
        multiple
        className="sr-only"
        onChange={(event) => onUpload(event.target.files)}
      />
    </header>
  )
}

import { FilmIcon } from "lucide-react"
import { ClientEmptyState } from "./client-empty-state"
import { ClipCard } from "./clip-card"
import type { ClientClip } from "./client-clip"
export function ClipsLibrary({
  clips,
  emptyStateTitle,
  onDownload,
  onDuplicate,
  onRemove,
}: {
  clips: ClientClip[]
  emptyStateTitle: string
  onDownload: (clip: ClientClip) => void
  onDuplicate: (clip: ClientClip) => void
  onRemove: (clip: ClientClip) => void
}) {
  if (!clips.length)
    return <ClientEmptyState icon={FilmIcon} title={emptyStateTitle} />
  return (
    <div className="space-y-2 py-6">
      {clips.map((clip) => (
        <ClipCard
          key={clip.id}
          clip={clip}
          onDownload={() => onDownload(clip)}
          onDuplicate={() => onDuplicate(clip)}
          onRemove={() => onRemove(clip)}
        />
      ))}
    </div>
  )
}

import type { LucideIcon } from "lucide-react"

export function ClientEmptyState({ icon: Icon, title, description }: { icon: LucideIcon; title: string; description?: string }) {
  return (
